INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "宋史·巻一", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2a8781f0b81874ff142e6f29547499414becd367/content/books/zizhi-tongjian/vol-291/year-0954/part-03/sources/library/songshi-1-gaoping-counterattack/source.txt", "note": "《宋史》巻一，段落 songshi-9c6e46fee832-p000512；EPUB电子本，纸本及异文待核", "id": "446a6f67-6e42-561d-bd9e-7b5141a72cf7"}, {"title": "宋史·巻一", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2a8781f0b81874ff142e6f29547499414becd367/content/books/zizhi-tongjian/vol-291/year-0954/part-03/sources/library/songshi-1-zhao-kuangyin-name/source.txt", "note": "《宋史》巻一，段落 songshi-9c6e46fee832-p000508；EPUB电子本，纸本及异文待核", "id": "a4ad0a0c-6366-5e6b-9665-60db62bf3ff4"}, {"title": "宋史·巻二百七十三", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2a8781f0b81874ff142e6f29547499414becd367/content/books/zizhi-tongjian/vol-291/year-0954/part-03/sources/library/songshi-273-ma-renyu-gaoping/source.txt", "note": "《宋史》巻二百七十三，段落 songshi-9c6e46fee832-p059130；EPUB电子本，纸本及异文待核", "id": "3c039af8-b991-544f-a125-f63854f9c8f0"}, {"title": "资治通鉴·后周纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2a8781f0b81874ff142e6f29547499414becd367/content/books/zizhi-tongjian/vol-291/year-0954/part-03/sources/library/tongjian-291-954-gaoping/source.txt", "note": "《资治通鉴》后周纪二，段落 zizhi-tongjian-a63549944a71-p003461；电子底本待考，分段待核", "id": "8b373934-94fe-5e2f-9ccc-a348ce6419fc"}, {"title": "旧五代史·卷114·世宗本纪一·显德元年三月亲征", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/073fb28ff5792b333432fe68e474ebdcc4b7db18/content/books/zizhi-tongjian/vol-291/year-0954/part-02/sources/library/jiuwudaishi-114-campaign-march-954/source.txt", "note": "《旧五代史》卷114·世宗本纪一·显德元年三月亲征，段落 jiu-wudaishi-205deb4a7860-p002707；已核上下文及传主，纸本及异文待核。", "id": "a16cc231-7682-57f7-9978-41bf21405923"}, {"title": "新五代史·卷12·周本纪第十二·柴荣即位", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/3ba4c15f89bc0e4a416ae35be0615a8c443b7f49/content/books/zizhi-tongjian/vol-291/year-0954/part-01/sources/library/xinwudaishi-12-chairong-accession/source.txt", "note": "《新五代史》卷12·周本纪第十二·柴荣即位，段落 xin-wudaishi-b08f244b9241-p000376；已核上下文及传主，纸本及异文待核。", "id": "e8e8d8ba-d759-5bf8-896c-ca674bd3a93d"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "刘崇（刘知远弟）", "aliases": ["劉崇（劉知遠弟）", "刘旻", "劉旻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的弟弟，后来名刘旻。947年任太原尹、知府事。与朱温早年寄居的萧县刘崇分别建档，具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "edf0bd63-ab6d-577e-8623-9f2d759b6d97"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "张元徽", "aliases": ["張元徽"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "武安人，刘崇的裨将。951年北汉建立时任马步军都指挥使。生卒年未载。", "biography": null, "status": "draft", "id": "b1a0aed5-927c-5e60-95b8-aea2894d7ad1"}, {"name": "杨衮", "aliases": ["楊袞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领。947年麻答派他率契丹及幽州兵援杜重威；他出兵后，恒州留守军减少，为当地起兵提供时机。生卒年未载。", "biography": null, "status": "draft", "id": "4115ee92-89ee-534e-a312-a3e1bd4793d6"}, {"name": "刘词", "aliases": ["劉詞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋奉国都指挥使，元城人。942年与王清率军先登襄州。生卒年未载。", "biography": null, "status": "draft", "id": "1d26caf6-67d4-52b5-a6df-b9dff192cea5"}, {"name": "白重赞", "aliases": ["白重贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周武成节度使。953年九月己亥奏报已堵塞决口的黄河。生卒年未载。", "biography": null, "status": "draft", "id": "b6889cb5-a3c4-5b6a-aa6e-7feda1afc895"}, {"name": "李重进", "aliases": ["李重進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "沧州人，福庆长公主之子，郭威的外甥，生于太原。郭威在藩镇时期的将佐，952年任恩州团练使，逐渐受重用。《宋史》还记当年内殿职务变化，具体任日未载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9769d0fb-1d80-593e-9aa3-e4c22416f835"}, {"name": "樊爱能", "aliases": ["樊愛能"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周马军将领。954年正月获领武定节度使，旧纪同时记其军职与洋州节度职衔。生卒年暂未核定。", "biography": null, "status": "draft", "id": "31b12a36-803d-574a-a818-05742d936537"}, {"name": "何徽", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周虎捷指挥使。951年与王万敢、史彦超共同抵御北汉、契丹对晋州的进攻。生卒年未载。", "biography": null, "status": "draft", "id": "2982109b-18cc-561f-9927-a98ba7b7f5e6"}, {"name": "向训", "aliases": ["向訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周军官。951年与陈思让参与虒亭战事，《旧五代史》称监军，《宋史》称都监。生卒年及后续改名尚未据本次引文录入。", "biography": null, "status": "draft", "id": "1d29bcb9-6ec9-5369-89ff-ea67f0460acc"}, {"name": "史彦超（后周将领）", "aliases": ["史彦超", "史彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "云州人，后周龙捷都指挥使。951年与王万敢、何徽防守晋州，抵抗北汉、契丹军。尚不与其他政权的同名将领合并，生卒年未录全。", "biography": null, "status": "draft", "id": "541b4701-1443-5a49-a822-4dc8d508ecee"}, {"name": "张永德", "aliases": ["張永德"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "阳曲人，郭威的女婿。950年任供奉官押班，奉命给昭义节度使常思送生日礼物；常思接到杀他的密诏后拘留观望，郭威取京师后释放并道歉。生卒年本批未录。", "biography": null, "status": "draft", "id": "c1584e5c-2a3c-5c28-bbe4-7c8a05161c51"}, {"name": "王延嗣", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 954, "description": "北汉副枢密使。954年高平之战前让司天监李义建议开战，当晚在后周军再次击败北汉时被杀。生年未载。", "biography": null, "status": "draft", "id": "e895b8ca-68d3-5e22-8d21-03e1f21aac94"}, {"name": "李义（北汉司天监）", "aliases": ["李义", "李義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "北汉司天监。954年高平之战前经王延嗣向刘崇表示可以开战，王得中反对这一建议。生卒年未载；不与其他朝代同名人物合并。", "biography": null, "status": "draft", "id": "e279063b-1a62-5b72-86a6-6aa0d4d2fb8a"}, {"name": "王得中", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "上党人，北汉枢密直学士。951年九月受刘崇派遣出使契丹，祝贺新君即位，并请求援兵进攻晋州。生卒年未载。", "biography": null, "status": "draft", "id": "24fc3a64-54f4-5587-8e68-cf8c2b329c89"}, {"name": "赵匡胤", "aliases": ["趙匡胤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周宿卫将领，后来成为宋太祖。954年高平之战右军溃逃后，与张永德分率两翼反击北汉军。《宋史》本纪印证其率同列冲锋的记载。生卒年留待相应史料补录。", "biography": null, "status": "draft", "id": "ce0fe2a6-d446-50c7-b968-4245fd9693ad"}, {"name": "马仁瑀", "aliases": ["馬仁瑀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "夏津人，后周内殿直。954年高平之战中骑马射敌，鼓舞士气；《宋史》马仁瑀传也记这次行动。生卒年本段未载。", "biography": null, "status": "draft", "id": "d2f479cf-a621-511c-8912-9bc00b29b68f"}, {"name": "马全乂", "aliases": ["馬全乂", "马全义", "馬全義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "原为李守贞麾下骑士，后事柴荣。953年随柴荣入朝，郭威召见并任命为殿前指挥使，称赞其忠于所事。《宋史》作马全义，记同一河中经历、任职和召见言论，复用同人异名；后续生卒另待录。", "biography": null, "status": "draft", "id": "dac95b9c-875b-5289-a14d-87b438c324fb"}, {"name": "唐景思（后周效顺指挥）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周前武胜行军司马。954年高平之战后奉命统领由数千北汉降卒组成的效顺指挥，戍守淮上。与925年前蜀故镇屯驻指挥使唐景思是否同人，缺少明确履历证据，暂作独立主体。", "biography": null, "status": "draft", "id": "9eb2e8d1-86ce-5167-8643-50c6f4a05994"}, {"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
